 FROM sessions s JOIN contentbehavior c ON c.cntsessref = s.sessref JOIN moderationaction m ON m.macntref = c.cntref JOIN securitydetection d ON d.secdetkey = m.masedetref GROUP BY s.accindex
), technical_totals AS (
 SELECT s.accindex, MAX(t.ipcountrynum) AS max_countries, MAX(t.vpnratio) AS max_vpnratio, MAX(t.proxycount) AS max_proxycount
 FROM sessions s JOIN networkmetrics n ON n.netsessref = s.sessref JOIN technicalinfo t ON t.technetref = n.netkey GROUP BY s.accindex
), top_five AS (
 SELECT a.accindex, COALESCE(r.srs, 0) * (1 + 0.2 * COALESCE(t.max_countries, 0)) AS cpri
 FROM account a LEFT JOIN session_totals sc ON sc.accindex = a.accindex LEFT JOIN posting_totals pt ON pt.accindex = a.accindex LEFT JOIN risk_totals r ON r.accindex = a.accindex LEFT JOIN technical_totals t ON t.accindex = a.accindex
 WHERE COALESCE(sc.session_count, 0) > 1000 OR COALESCE(pt.total_post_frequency, 0) > 50
 ORDER BY cpri DESC LIMIT 5
)
SELECT AVG(0.4 * t.max_vpnratio + 0.3 * t.max_proxycount / 10.0 + 0.3 * t.max_countries / 20.0) AS average_tei
FROM top_five f JOIN technical_totals t ON t.accindex = f.accindex;

WITH sessions AS (
 SELECT p.profaccref AS accindex, s.sessref FROM profile p JOIN sessionbehavior s ON s.sessprofref = p.profkey
), session_totals AS (
 SELECT accindex, COUNT(*) AS session_count FROM sessions GROUP BY accindex
), posting_totals AS (
 SELECT s.accindex, SUM(c.postfreq) AS total_post_frequency FROM sessions s JOIN contentbehavior c ON c.cntsessref = s.sessref GROUP BY s.accindex
), risk_totals AS (
